// Brixelizer's shader blob accessor (ADR 0090), in place of the SDK's
// sdk/src/backends/shared/blob_accessors/ffx_brixelizer_shaderblobs.cpp, which includes
// headers generated by the SDK's shader compiler: the reflection and the permutation table
// in permutations_brixelizer.inc, the SPIR-V from Rust (src/blobs.rs), both from
// examples/ffx_shaders.rs.

#include "ffx_engine.h"

#include <FidelityFX/host/ffx_util.h>
#include "ffx_brixelizer_shaderblobs.h"
#include "brixelizer/ffx_brixelizer_raw_private.h"

#include <cstring>

namespace {

#include "permutations_brixelizer.inc"

}  // namespace

FfxErrorCode brixelizerGetPermutationBlobByIndex(FfxBrixelizerPass passId, uint32_t permutationOptions, FfxShaderBlob* outBlob)
{
    // The generator's shaders follow `FfxBrixelizerPass`; no pass has options that map to
    // defines, and every one has a 16-bit variant.
    if (uint32_t(passId) >= uint32_t(FFX_BRIXELIZER_PASS_COUNT))
    {
        std::memset(outBlob, 0, sizeof(FfxShaderBlob));
        return FFX_ERROR_INVALID_ARGUMENT;
    }
    const uint32_t fp16 = FFX_CONTAINS_FLAG(permutationOptions, BRIXELIZER_SHADER_PERMUTATION_ALLOW_FP16) ? 1 : 0;
    return engineFfxBlob(ENGINE_FFX_BRIXELIZER, g_permutations, sizeof(g_permutations) / sizeof(g_permutations[0]),
                         g_reflection, MODULE_COUNT, uint32_t(passId), fp16, 0, outBlob);
}

FfxErrorCode brixelizerIsWave64(uint32_t permutationOptions, bool& isWave64)
{
    // The same module either way on Vulkan: the backend requests the subgroup size.
    isWave64 = FFX_CONTAINS_FLAG(permutationOptions, BRIXELIZER_SHADER_PERMUTATION_FORCE_WAVE64);
    return FFX_OK;
}
